  Item_10105_Name = {
    Text = "Crisálida da jovem Ⅰ"
  },
  Item_10105_StoryDesc = {
    Text = "Ofereço-lhe um corpo puro"
  },
  Item_10106_Desc = {
    Text = "Suprimentos abundantes aprovados pelo Decano interino Czort.\nCaixa de madeira contendo materiais valiosos, fornecendo assistência aos Guardiões do segredo na execução dos treinamentos.\nEscolha um dos seguintes materiais:\nCapítulo Secreto Puro Branco*12\nTemperar a mente*12\nCópia de consciência*12\nModelo de Gnosis*12"
  },
  Item_10106_Name = {
    Text = "Ⅱ Nível de Suprimento (Desativado)"
  },
  Item_10107_Desc = {
    Text = "A essência do pacto consiste em conhecimento tabu e difícil de ser compreendido. Após o uso da cópia para reter o desenho, o poder do pacto será ainda mais fortalecido"
  },
  Item_10107_Name = {
    Text = "Transcrição do pacto (abandonado)"
  },
  Item_10108_Desc = {
    Text = "Nome elegante da moeda do reino. Pode ser obtida em qualquer lugar e usada para tudo"
  },
  Item_10108_Name = {
    Text = "Cupom de ouro rosa"
  },
  Item_10110_Desc = {
    Text = "Atributo principal: obtenha aleatoriamente 1 de maestria de reino, queda de sigilo negro, resistência à morte ou potência de dano"
  },
  Item_10110_Name = {
