  Item_10111_Name = {
    Text = "Anel das 36 Salas Ⅰ"
  },
  Item_10111_StoryDesc = {
    Text = "Girar e esquecer—isso é toda a sua vida"
  },
  Item_10112_Desc = {
    Text = "Após o ritual de despertar, a espuma deixada na \"Piscina Negra\". Talvez apenas comerciantes de outras dimensões consigam compreender seu valor?"
  },
  Item_10112_Name = {
    Text = "Espuma da origem (descartada)"
  },
  Item_10113_Desc = {
    Text = "Casa com vazamentos. Melhor que nada.\nCasulo abandonado. Usado para aumentar o nível de habilidade do Despertado do Reino da Carne"
  },
  Item_10113_Name = {
    Text = "Pupas desidratadas"
  },
  Item_10114_Desc = {
    Text = "Isso é a consciência perdida da antiga vontade. Misaq inspira a consciência do Corpo Desperto através de um ritual misterioso, e a consciência despertada aprimorará permanentemente a capacidade espiritual.\nConversão ao obter \"24\" repetidamente, usada para ativar o Despertar Espiritual de \"24\"."
  },
  Item_10114_Name = {
    Text = "Fragmento·\"24\""
  },
  Item_10114_StoryDesc = {
    Text = "Converte ao repetir a obtenção de \"24\", necessário para ativar a iluminação de \"24\""
  },
  Item_10115_Desc = {
