  Item_123483_Desc = {
    Text = "Adquirido após a compra do \"Tema principal\" no \"Registro de temas\".\n\"Minhas antigas correntes? Agora são as armas que usarei para acorrentar meus opressores!\""
  },
  Item_123483_Name = {
    Text = "Ontem que não desvanece: Helot: Catena"
  },
