  Item_141226_Name = {
    Text = "\"Presa\" Primordial"
  },
  Item_141227_Desc = {
    Text = "Feche os olhos, tampe os ouvidos e repita comigo: é um peixe, é um peixe. Isso mesmo — seja lá o que habita neste campo de caça, é apenas um peixe.\n\nCai pelo menos {s1}"
  },
  Item_141227_Name = {
    Text = "\"Presa\" Primordial"
  },
  Item_141228_Desc = {
    Text = "É de conhecimento geral que peixes abissais crescem de forma descontrolada. Ser monstruosamente grande é normal... Parecer com humanos também é completamente normal.\n\nCai pelo menos {s1}"
  },
  Item_141228_Name = {
    Text = "\"Presa\" Colossal"
  },
  Item_141229_Desc = {
    Text = "É a consciência perdida de uma vontade ancestral. O Misaq desperta a consciência do Corpo Desperto por meio de rituais misteriosos, e o Corpo Desperto iluminado terá suas capacidades mentais permanentemente aumentadas.\nObtido por conversão ao adquirir Pontos repetidamente, usado para ativar o Despertar Espiritual de Pontos."
  },
  Item_141229_Name = {
    Text = "Fragmento·Pontos"
  },
  Item_141229_StoryDesc = {
    Text = "Obtido por conversão ao adquirir Pontos repetidamente, usado para ativar o Despertar Espiritual de Pontos."
  },
  Item_141230_Desc = {
    Text = "Não se pergunte por que os peixes correm em terra — aqui é Ebwynnos."
