  Item_61391_Desc = {
    Text = "A roda do destino com a propriedade do nível de recarga de chave de prata"
  },
  Item_61391_Name = {
    Text = "Coração de Prata"
  },
  Item_61391_StoryDesc = {
    Text = "Era um coração prateado, puro e imaculado.\nEra feito de prata pura, batendo de maneira ordenada dentro de uma estrutura mecânica.\nJá foi corrompido pelo sangue e carne, e manchado pela lama.\nMas quando a sombra da morte se aproximou, ele finalmente voltou à sua forma primordial"
  },
  Item_61941_Desc = {
    Text = "O luar a envolve em branco prateado, celebrando o nascimento de uma vida indomável.\nUm broto recém-florescido no topo de Elworth, usado para trocar itens em \"Fúria de Vingança\".\n\nDrops at least {s1}"
  },
  Item_61941_Name = {
    Text = "Brotinho de prata com geada"
  },
  Item_61942_Desc = {
    Text = "A luz do sol a envolve em amarelo dourado, celebrando o nascimento de uma vida indomável.\nUm broto recém-florescido no topo de Elworth, usado para trocar itens em \"Esperança de Ressurreição\".\n\nDrops at least {s1}"
