  Item_72089_Desc = {
    Text = "\"As bolotas representam o início de uma aventura, precisamos de mais bolotas!\" - Ignatis. Bolotas formadas pela magia de Ignatis, utilizadas para intercâmbio de suprimentos em \"Turno Extraordinário\"."
  },
  Item_72089_Name = {
    Text = "Avelã mágica"
  },
  Item_72089_StoryDesc = {
    Text = "Evento de colaboração de reversão de turno"
  },
  Item_72095_Desc = {
    Text = "Após registrar esta Ordem de chave, você pode selecionar a Habilidade de chave: \"A porta da taverna\" durante a formação da Fase de Duelo.\n\nQuando um mundo chega ao fim, o prólogo de outro mundo já se inicia. A história será continuamente contada junto com o vinho, mas o tempo escreverá respostas para todas as coisas."
  },
  Item_72095_Name = {
    Text = "A porta da taverna"
  },
  Item_72095_StoryDesc = {
    Text = "Quando um mundo chega ao fim, o prólogo de outro mundo já se inicia. A história será continuamente contada junto com o vinho, mas o tempo escreverá respostas para todas as coisas."
  },
  Item_72824_Desc = {
    Text = "Um pequeno bar localizado no continente de Herpland, que possui um portal capaz de conectar a diferentes mundos. \nA proprietária do bar, Ignatius, criou um jogo de cartas chamado Cartas do Mundo, com o objetivo de contar as histórias dos heróis do passado.\n\n."
  },
  Item_72824_Name = {
    Text = "Reverter o turno: Carta do Mundo"
  },
  Item_72824_StoryDesc = {
    Text = "Evento de colaboração de reversão de turno"
  },
  Item_72834_Desc = {
    Text = "Chance de obter através do \"Voucher do Invisível\".\n\"Oh, alguém quer experimentar o meu novo chá especial de aranha?\""
  },
  Item_72834_Name = {
    Text = "Em nome da Chave de Prata: Sílvia"
  },
  Item_72834_StoryDesc = {
    Text = "Voucher Exclusivo de Coleção de Aparência"
  },
  Item_72835_Desc = {
    Text = "Recompensa de conquista no evento \"Tecelão Aprisionado\".\n\"Oh, por favor, não interrompa meu têxtil—não há nada mais importante do que isso...\""
  },
  Item_72835_Name = {
    Text = "Em nome da Chave de Prata: Aracne"
  },
  Item_72835_StoryDesc = {
    Text = "Atividade do Modo Aracne"
  },
  Item_72836_Desc = {
