  Item_80189_Name = {
    Text = "Pacote Super Valor Vazio"
  },
  Item_80191_Desc = {
    Text = "Após gravar este Bando, você pode escolher a habilidade de bando: \"Cura Especial\" durante a formação da equipe.\n\nEla curou inúmeros pacientes, guiando-os à renascença, e tudo agora é apenas um tratamento psicológico.\nA única coisa especial é que a paciente é ela mesma."
  },
  Item_80191_Name = {
    Text = "Tratamento Especial"
  },
  Item_80191_StoryDesc = {
    Text = "Ela já curou inúmeros pacientes, guiando-os em direção a uma nova vida; agora, tudo isso não passa de uma sessão de terapia psicológica. \nA única diferença é que a paciente é ela mesma."
  },
  Item_80192_Desc = {
    Text = "Partículas emocionais dispersas pelo Sanatório Mental, ao tocá-las parece ouvir o murmúrio de alguém à beira do colapso. \nUsado para aumentar a ressonância do Guardião do Segredo durante a investigação do evento \"Transformação\"."
  },
  Item_80192_Name = {
    Text = "Coração da Cognição"
  },
  Item_80285_Desc = {
    Text = "Após desbloquear, completar todas as missões de \"Viagem Terapêutica\" concede as seguintes recompensas adicionais"
  },
  Item_80285_Name = {
    Text = "Crônica do Sanatório"
  },
  Item_81021_Desc = {
    Text = "Ferramenta de limpeza especial de Karen, capaz de limpar qualquer coisa de maneira suave e eficaz."
