  Item_95513_Name = {
    Text = "Captura de Essência · Esquecimento"
  },
  Item_95514_Desc = {
    Text = "Um antigo texto misterioso que contém profecias de dimensões estranhas.\nÉ possível escolher gratuitamente 1 destino limitado no domínio \"Transcendental\" dos \"Capítulos Esquecidos\"."
  },
  Item_95514_Name = {
    Text = "Profecia Superdimensional · Esquecimento"
